from __future__ import absolute_import
from taf.selenium.sbts.pages import login_management
from .modals import LegalNoticeModal


class SbtsLoginPage(login_management.SbtsLoginPage):

    def __init__(self, webdriver, screenshot_dir):
        super(SbtsLoginPage, self).__init__(webdriver, screenshot_dir)
        self._legal_notice_modal = LegalNoticeModal(webdriver)


class LogoutPage(login_management.LogoutPage):
    """
    A class manages logout page, logout function included.
    """
    _USER_COUNT_VIEW_XPATH = '//otx-user-account'
    _LOGOUT_BUTTON_XPATH = '//div[@class="otx-element-middle" and text()="Logout"]'
